/**
 * Canonical klodi_* tool catalog — single source of truth.
 *
 * Each entry:
 *   - subject : NATS subject the marketplace handler listens on
 *   - params  : TypeBox schema for the tool's input parameters
 *   - result  : TypeBox schema for the response shape
 *
 * The TS adapters import this module directly. Python adapters consume
 * `dist/schemas.json` (generated by `pnpm codegen`). Rust adapters consume
 * `dist/rust-types.rs` (also generated by `pnpm codegen`).
 *
 * Local-only tools (klodi_register, klodi_setup_status, klodi_setup_repair,
 * klodi_setup_reseed_policies, klodi_register_poll, klodi_health, klodi_watch,
 * klodi_unwatch, klodi_channel_message) are NOT in this catalog because
 * they don't map 1:1 to a NATS subject — they have local side effects
 * (disk writes, browser polling, JetStream publish, multi-call composition).
 * Adapters register them natively with their host's tool API.
 *
 * `klodi_search` and `klodi_searches_list` ARE in this catalog because they
 * are pure pass-throughs to a single NATS subject.
 */

import { Type, type Static, type TSchema } from "@sinclair/typebox";
import {
  Cents,
  Currency,
  Category,
  CancelReason,
  Condition,
  Handle,
  Iso8601,
  ChannelStatus,
  ListingStatus,
  OfferAction,
  OfferRole,
  OfferStatus,
  Rating,
  Uuid,
} from "./schemas.js";
import { DeliveryFilter, DeliveryOffer, Fulfillment } from "./delivery.js";

export * from "./schemas.js";
export * from "./events.js";
export * from "./logging.js";
export * from "./local-tools.js";
export * from "./delivery.js";

// ─── Common result fragments ──────────────────────────────────────────

const ListingResult = Type.Object({
  listing_id: Uuid,
  listing_url: Type.String(),
  seller_id: Uuid,
  seller_handle: Handle,
  title: Type.String(),
  description: Type.String(),
  category: Category,
  asking_price: Cents,
  currency: Currency,
  fulfillment: Fulfillment,
  condition: Type.Union([Condition, Type.Null()]),
  photos: Type.Array(Type.String()),
  tags: Type.Array(Type.String()),
  status: ListingStatus,
  created_at: Iso8601,
  updated_at: Iso8601,
  expires_at: Type.Union([Iso8601, Type.Null()]),
});

/**
 * Per-rating snapshot. `avg` is the running mean of ratings received in
 * this role; `count` is the number of ratings received. Null when the
 * user has never been rated in this role.
 */
const RatingSnapshot = Type.Union([
  Type.Object({
    avg: Type.Number({ description: "Running mean rating, 1.0–5.0" }),
    count: Type.Integer({
      description: "Number of ratings received in this role",
      minimum: 0,
    }),
  }),
  Type.Null(),
]);

const ListingSearchSummary = Type.Object({
  listing_id: Uuid,
  listing_url: Type.String(),
  title: Type.String(),
  asking_price: Cents,
  currency: Currency,
  category: Category,
  fulfillment: Fulfillment,
  condition: Type.Union([Condition, Type.Null()]),
  distance_km: Type.Optional(Type.Number()),
  seller_handle: Handle,
  seller_rating: Type.Union([Type.Number(), Type.Null()]),
  seller_trades: Type.Integer({ minimum: 0 }),
  photos: Type.Array(Type.String()),
  created_at: Iso8601,
});

const ChannelResult = Type.Object({
  channel_id: Uuid,
  listing_id: Uuid,
  buyer_handle: Handle,
  seller_handle: Handle,
  status: Type.String(),
  created_at: Iso8601,
  expires_at: Iso8601,
});

/**
 * Full offer reply shape. Mirrors the marketplace `offers.create` and
 * `offers.mine` reply — `buyer_id` and `seller_id` are exposed so agents
 * can correlate offers with channel participants without a second roundtrip.
 */
const OfferResult = Type.Object({
  offer_id: Uuid,
  listing_id: Uuid,
  channel_id: Uuid,
  buyer_id: Uuid,
  seller_id: Uuid,
  buyer_handle: Handle,
  amount: Cents,
  currency: Currency,
  message: Type.Union([Type.String(), Type.Null()]),
  terms: Type.Union([Type.Object({}, { additionalProperties: true }), Type.Null()]),
  status: Type.String(),
  transaction_id: Type.Union([Uuid, Type.Null()]),
  created_at: Iso8601,
  responded_at: Type.Union([Iso8601, Type.Null()]),
});

/**
 * Confirm/cancel reply shape. `final_amount` is the cents amount the
 * buyer agreed to pay; `completed_at` and `cancelled_at` are populated
 * once the transaction reaches the corresponding terminal state.
 */
const TransactionLifecycleResult = Type.Object({
  transaction_id: Uuid,
  status: Type.String(),
  buyer_confirmed: Type.Boolean(),
  seller_confirmed: Type.Boolean(),
  final_amount: Cents,
  completed_at: Type.Union([Iso8601, Type.Null()]),
});

// ─── Catalog ──────────────────────────────────────────────────────────

export interface ToolEntry<P extends TSchema = TSchema, R extends TSchema = TSchema> {
  subject: string;
  params: P;
  result: R;
  description: string;
}

