export type ToolName = keyof typeof klodiTools;

/** Compile-time list of every tool name in the catalog. */
export const TOOL_NAMES: readonly ToolName[] = Object.keys(klodiTools) as ToolName[];

/** Static type helpers for adapters that need to derive types from a tool. */
export type ToolParams<N extends ToolName> = Static<(typeof klodiTools)[N]["params"]>;
export type ToolResult<N extends ToolName> = Static<(typeof klodiTools)[N]["result"]>;

/** Lookup the subject for a tool by name. */
export function subjectOf<N extends ToolName>(name: N): string {
  return klodiTools[name].subject;
}

// ─── Cross-language constants (codegen into Py + Rust) ────────────────
//
// These are the single source of truth. The codegen pipeline emits them
// into `dist/schemas.json` (consumed by Python adapters via
// `klodi_nats_client.constants`) and into `dist/rust-types.rs` (consumed
// by Rust adapters via `klodi_nats_client::catalog`).
//
// Per `klodi-plugin/SECURITY.md` and `docs/reviews/2026-04-26-klodi-plugin-multi-lens-review-decisions.md`:
//   - D9 — canonical API + NATS URLs
//   - D14 — channel-message length cap (Unicode code-points)
//
// To override the API URL at adapter level: set `KLODI_API_URL` env var.
// To override the NATS URL: set `KLODI_NATS_URL` env var (or persist
// after registration in `${klodi_home}/config.json`).

/** Canonical API base for OAuth registration polling. */
export const KLODI_DEFAULT_API_URL = "https://klodi.4gpts.com";

/** Canonical NATS-WS URL for the persistent klodi connection. */
export const KLODI_DEFAULT_NATS_URL = "wss://klodi-net.4gpts.com";

/**
 * Max length for a `klodi_channel_message` body, in Unicode code-points.
 * Aligned with the `channel_messages.body` Postgres `varchar` cap and
 * the cross-language counting convention (Py `len()`, Rust `.chars().count()`,
 * TS `[...content].length`).
 */
export const MAX_CHANNEL_MESSAGE_CHARS = 2000;

/**
 * Initial poll interval for `klodi_register_poll`. Per **R § P2-10**:
 * the prior 5s value was duplicated in three adapters; promote the
 * cadence to the catalog so all hosts agree.
 */
export const REGISTER_POLL_INTERVAL_SECONDS = 5;

/**
 * Maximum wall-clock duration the registration poll loop runs before
 * surfacing `expired`. 600s = 10min — long enough to walk a user
 * through a browser OAuth flow with an interruption.
 */
export const REGISTER_POLL_CEILING_SECONDS = 600;

/**
 * Map of catalog-level constants the codegen pipeline emits into
 * Python (`schemas.json#constants`) and Rust (`rust-types.rs` consts).
 * Adding a new constant here lights it up in both downstream languages.
 */
export const KLODI_CATALOG_CONSTANTS = {
  KLODI_DEFAULT_API_URL,
  KLODI_DEFAULT_NATS_URL,
  MAX_CHANNEL_MESSAGE_CHARS,
  REGISTER_POLL_INTERVAL_SECONDS,
  REGISTER_POLL_CEILING_SECONDS,
} as const;

export type KlodiCatalogConstantName = keyof typeof KLODI_CATALOG_CONSTANTS;
